namespace g2m {
namespace {
using json = nlohmann::json;
// const unsigned char kRoadRulesDe[]: the bytes of data/road_rules/de.json, generated by CMake.
#include "road_rules_de.inc"

using strict::Reader;
constexpr std::int64_t kMaxMm = 20000;
// P2 lengths: every one in (0, 200] m (design 8.1).
constexpr std::int64_t kMaxLengthMm = 200000, kMaxLengthM = 200;
constexpr std::int64_t kMaxCornerRadiusMm = 30000;

bool read_junction_rules(Reader& rd, const json& root, JunctionRules& out) {
    const auto* j = rd.field(root, "root", "junction");
    static constexpr const char* kPath = "junction";
    if (!j || !rd.keys(*j, kPath, {"trim_min_mm", "trim_margin_mm", "edge_station_spacing_mm", "link_trim_cap_m", "cluster_max_extent_m",
            "cluster_max_nodes", "reach_max_m", "bowtie_rounds", "bowtie_step_mm", "corner_radius_mm", "corner_min_wedge_deg",
            "corner_tangent_max_percent", "corner_oneway_pair_radius_mm", "corner_oneway_pair_max_wedge_deg"})) return false;
    if (!rd.integer(*j, kPath, "trim_min_mm", 1, kMaxLengthMm, out.trim_min_mm) ||
        !rd.integer(*j, kPath, "trim_margin_mm", 1, kMaxLengthMm, out.trim_margin_mm) ||
        !rd.integer(*j, kPath, "edge_station_spacing_mm", 1, kMaxLengthMm, out.edge_station_spacing_mm) ||
        !rd.integer(*j, kPath, "link_trim_cap_m", 1, kMaxLengthM, out.link_trim_cap_m) ||
        !rd.integer(*j, kPath, "cluster_max_extent_m", 1, kMaxLengthM, out.cluster_max_extent_m) ||
        !rd.integer(*j, kPath, "cluster_max_nodes", 1, 12, out.cluster_max_nodes) || // the encoding stores 1..12 nodes per junction
        !rd.integer(*j, kPath, "reach_max_m", 1, kMaxLengthM, out.reach_max_m) ||
        !rd.integer(*j, kPath, "bowtie_rounds", 0, 16, out.bowtie_rounds) ||
        !rd.integer(*j, kPath, "bowtie_step_mm", 1, kMaxLengthMm, out.bowtie_step_mm) ||
        !rd.integer(*j, kPath, "corner_min_wedge_deg", 1, 179, out.corner_min_wedge_deg) ||
        !rd.integer(*j, kPath, "corner_tangent_max_percent", 100, 1000, out.corner_tangent_max_percent) ||
        !rd.integer(*j, kPath, "corner_oneway_pair_radius_mm", 0, kMaxCornerRadiusMm, out.corner_oneway_pair_radius_mm) ||
        !rd.integer(*j, kPath, "corner_oneway_pair_max_wedge_deg", 0, 179, out.corner_oneway_pair_max_wedge_deg)) return false;
    {
        // Corner radii per highway class: every key a class of the default road style or "default", 0..30 m.
        const std::string path = std::string(kPath) + ".corner_radius_mm";
        const auto* radii = rd.field(*j, kPath, "corner_radius_mm");
        if (!radii || !rd.object(*radii, path)) return false;
        std::set<std::string> known;
        for (const auto& entry : RoadStyle::default_style().highways) known.emplace(std::string(entry.highway));
        for (auto it = radii->begin(); it != radii->end(); ++it) {   // ascending key order
            if (it.key() != "default" && !known.contains(it.key())) return rd.fail(path + ": unknown class '" + it.key() + "'");
            if (!it.value().is_number_integer() || it.value().get<std::int64_t>() < 0 || it.value().get<std::int64_t>() > kMaxCornerRadiusMm)
                return rd.fail(path + "." + it.key() + " must be an integer in [0, 30000]");
            if (it.key() != "default") out.corner_radius_mm.emplace_back(it.key(), it.value().get<std::int32_t>());
        }
        if (!rd.integer(*radii, path, "default", 0, kMaxCornerRadiusMm, out.corner_radius_default_mm)) return false;
    }
    // Design 5.2: cluster discovery from the owner node visits nodes within extent + one link (2 trim caps) and that
    // must stay inside the 128 m halo that roads.graph keeps (reach_max_m).
    if (out.cluster_max_extent_m + 2 * out.link_trim_cap_m > out.reach_max_m)
        return rd.fail("junction: cluster_max_extent_m + 2 * link_trim_cap_m exceeds reach_max_m");
    // Design 5.3: every junction that can touch an L0 tile has its owner within reach + blend + extent of it.
    if (out.reach_max_m + kCarveBlendMaxM + out.cluster_max_extent_m > kCarverRadiusM)
        return rd.fail("junction: reach_max_m + 15 + cluster_max_extent_m exceeds the 192 m carver radius");
    return true;
}

bool read_pattern_map(Reader& rd, const json& parent, const std::string& parent_path, const char* key,
    std::vector<CrossingPatternEntry>& out) {
    static constexpr const char* kNames[kCrossingPatternCount] = {"none", "zebra", "dashes", "ladder", "lines", "surface"};
    const auto* map = rd.field(parent, parent_path, key);
    const std::string path = parent_path + "." + key;
    if (!map || !rd.object(*map, path)) return false;
    if (map->empty()) return rd.fail(path + " must not be empty");
    for (auto it = map->begin(); it != map->end(); ++it) { // nlohmann objects iterate in ascending key order
        if (it.key().empty() || it.key() == "yes") return rd.fail(path + ": key '" + it.key() + "' is not allowed");
        if (!it.value().is_string()) return rd.fail(path + "." + it.key() + " must be a string");
        const std::string& name = it.value().get_ref<const std::string&>();
        bool found = false;
        for (std::size_t p = 0; p < kCrossingPatternCount && !found; ++p) {
            if (name == kNames[p]) { out.push_back({it.key(), static_cast<CrossingPattern>(p)}); found = true; }
        }
        if (!found) return rd.fail(path + "." + it.key() + ": unknown pattern '" + name + "'");
    }
    return true;
}

bool read_furniture_rules(Reader& rd, const json& root, FurnitureRules& out) {
    const auto* f = rd.field(root, "root", "furniture");
    static constexpr const char* kPath = "furniture";
    if (!f || !rd.keys(*f, kPath, {"crossing_length_mm", "stop_line_before_crossing_mm", "junction_stop_setback_mm", "sign_line_setback_mm",
            "line_width_mm", "signal_assoc_max_m", "sign_assoc_max_m", "signal_lateral_offset_mm", "signal_left_min_lanes",
            "crossing_markings", "crossing_kind"})) return false;
    const auto* length = rd.field(*f, kPath, "crossing_length_mm");
    if (!length || !rd.keys(*length, "furniture.crossing_length_mm", {"zebra", "signalised", "other"}) ||
        !rd.integer(*length, "furniture.crossing_length_mm", "zebra", 1, kMaxLengthMm, out.crossing_zebra_mm) ||
        !rd.integer(*length, "furniture.crossing_length_mm", "signalised", 1, kMaxLengthMm, out.crossing_signalised_mm) ||
        !rd.integer(*length, "furniture.crossing_length_mm", "other", 1, kMaxLengthMm, out.crossing_other_mm)) return false;
    const auto* width = rd.field(*f, kPath, "line_width_mm");
    if (!width || !rd.keys(*width, "furniture.line_width_mm", {"stop", "give_way", "signal"}) ||
        !rd.integer(*width, "furniture.line_width_mm", "stop", 1, kMaxLengthMm, out.line_stop_mm) ||
        !rd.integer(*width, "furniture.line_width_mm", "give_way", 1, kMaxLengthMm, out.line_give_way_mm) ||
        !rd.integer(*width, "furniture.line_width_mm", "signal", 1, kMaxLengthMm, out.line_signal_mm)) return false;
    if (!rd.integer(*f, kPath, "stop_line_before_crossing_mm", 1, kMaxLengthMm, out.stop_line_before_crossing_mm) ||
        !rd.integer(*f, kPath, "junction_stop_setback_mm", 1, kMaxLengthMm, out.junction_stop_setback_mm) ||
        !rd.integer(*f, kPath, "sign_line_setback_mm", 1, kMaxLengthMm, out.sign_line_setback_mm) ||
        !rd.integer(*f, kPath, "signal_assoc_max_m", 1, kMaxLengthM, out.signal_assoc_max_m) ||
        !rd.integer(*f, kPath, "sign_assoc_max_m", 1, kMaxLengthM, out.sign_assoc_max_m) ||
        !rd.integer(*f, kPath, "signal_lateral_offset_mm", 1, kMaxLengthMm, out.signal_lateral_offset_mm) ||
        !rd.integer(*f, kPath, "signal_left_min_lanes", 1, 16, out.signal_left_min_lanes)) return false;
    return read_pattern_map(rd, *f, kPath, "crossing_markings", out.crossing_markings) &&
           read_pattern_map(rd, *f, kPath, "crossing_kind", out.crossing_kind);
}

bool read_tunnel_rules(Reader& rd, const json& root, TunnelRules& out) {
    const auto* t = rd.field(root, "root", "tunnel");
    static constexpr const char* kPath = "tunnel";
    return t && rd.keys(*t, kPath, {"straight_grade_min_length_m"}) &&
           rd.integer(*t, kPath, "straight_grade_min_length_m", 0, 100000, out.straight_grade_min_length_m);
}

const CrossingPattern* find_pattern(const std::vector<CrossingPatternEntry>& table, std::string_view value) {
    const auto it = std::lower_bound(table.begin(), table.end(), value,
        [](const CrossingPatternEntry& e, std::string_view v) { return e.value < v; });
    return it != table.end() && it->value == value ? &it->pattern : nullptr;
}
} // namespace

const CrossingPattern* FurnitureRules::find_marking(std::string_view value) const { return find_pattern(crossing_markings, value); }
const CrossingPattern* FurnitureRules::find_kind(std::string_view value) const { return find_pattern(crossing_kind, value); }

std::int32_t JunctionRules::corner_radius_for(std::string_view highway) const {
    const auto it = std::lower_bound(corner_radius_mm.begin(), corner_radius_mm.end(), highway,
        [](const std::pair<std::string, std::int32_t>& e, std::string_view h) { return e.first < h; });
    return it != corner_radius_mm.end() && it->first == highway ? it->second : corner_radius_default_mm;
}

const RoadClassRules* RoadRules::find_class(std::string_view highway) const {
    const auto it = std::lower_bound(classes.begin(), classes.end(), highway,
        [](const RoadClassRules& c, std::string_view h) { return c.highway < h; });
    return it != classes.end() && it->highway == highway ? &*it : nullptr;
}

Result<RoadRules> load_road_rules(std::span<const std::byte> bytes) {
    const char* begin = reinterpret_cast<const char*>(bytes.data());
    const json j = json::parse(begin, begin + bytes.size(), nullptr, /*allow_exceptions=*/false);
    if (j.is_discarded()) return make_error(ErrorCode::Malformed, "road rules: not valid JSON");
    Reader rd;
    const auto fail = [&]() { return make_error(ErrorCode::InvalidArgument, "road rules: " + rd.err); };
    if (!rd.keys(j, "root", {"format", "country", "min_lane_mm", "added_lane_side", "cycle_lane_mm", "sidewalk_mm", "tagged_shoulder_mm",
            "parking_mm", "traffic_calming", "junction", "furniture", "tunnel", "min_edge_radius_m", "classes", "sources"})) return fail();
    std::string format;
    if (!rd.text(j, "root", "format", format)) return fail();
    if (format != "g2m.road_rules/1") return make_error(ErrorCode::Unsupported, "road rules: format '" + format + "'");
    RoadRules rules;
    std::string side;
    if (!rd.text(j, "root", "country", rules.country) || !rd.text(j, "root", "added_lane_side", side) ||
        !rd.integer(j, "root", "min_lane_mm", 1, kMaxMm, rules.min_lane_mm) ||
        !rd.integer(j, "root", "cycle_lane_mm", 1, kMaxMm, rules.cycle_lane_mm) ||
        !rd.integer(j, "root", "sidewalk_mm", 1, kMaxMm, rules.sidewalk_mm) ||
        !rd.integer(j, "root", "tagged_shoulder_mm", 1, kMaxMm, rules.tagged_shoulder_mm)) return fail();
    if (rules.country.empty()) { rd.fail("country must not be empty"); return fail(); }
    if (side == "right") rules.added_lane_side = AddedLaneSide::Right;
    else if (side == "left") rules.added_lane_side = AddedLaneSide::Left;
    else { rd.fail("added_lane_side must be \"left\" or \"right\""); return fail(); }
    const auto* parking = rd.field(j, "root", "parking_mm");
    if (!parking || !rd.keys(*parking, "parking_mm", {"parallel", "diagonal", "perpendicular"}) ||
        !rd.integer(*parking, "parking_mm", "parallel", 1, kMaxMm, rules.parking_mm[0]) ||
        !rd.integer(*parking, "parking_mm", "diagonal", 1, kMaxMm, rules.parking_mm[1]) ||
        !rd.integer(*parking, "parking_mm", "perpendicular", 1, kMaxMm, rules.parking_mm[2])) return fail();
    {
        static constexpr const char* kKinds[kProfileFeatureKindCount] = {"bump", "mini_bumps", "rumble_strip", "cushion", "hump",
            "table", "chicane", "choker", "island", "dip"};
        const auto* calming = rd.field(j, "root", "traffic_calming");
        if (!calming || !rd.keys(*calming, "traffic_calming", {"bump", "mini_bumps", "rumble_strip", "cushion", "hump", "table",
                "chicane", "choker", "island", "dip"})) return fail();
        for (std::size_t k = 0; k < kProfileFeatureKindCount; ++k) {
            const std::string path = std::string("traffic_calming.") + kKinds[k];
            const auto* entry = rd.field(*calming, "traffic_calming", kKinds[k]);
            if (!entry || !rd.keys(*entry, path, {"length_mm", "height_mm", "width_mm"})) return fail();
            auto& out = rules.traffic_calming[k];
            if (!rd.integer(*entry, path, "length_mm", 1, 50000, out.length_mm) || !rd.integer(*entry, path, "height_mm", 0, 300, out.height_mm) ||
                !rd.integer(*entry, path, "width_mm", 0, 100000, out.width_mm)) return fail();
        }
    }
    if (!read_junction_rules(rd, j, rules.junction) || !read_furniture_rules(rd, j, rules.furniture) || !read_tunnel_rules(rd, j, rules.tunnel)) return fail();
    const auto* sources = rd.field(j, "root", "sources");
    if (!sources || !rd.object(*sources, "sources")) return fail();
    for (auto it = sources->begin(); it != sources->end(); ++it)
        if (!it.value().is_string()) { rd.fail("sources." + it.key() + " must be a string"); return fail(); }

    // The classes that must have rules: every highway value the default road style accepts.
    std::set<std::string> required;
    for (const auto& entry : RoadStyle::default_style().highways) required.emplace(std::string(entry.highway));
    const auto* radii = rd.field(j, "root", "min_edge_radius_m");
    if (!radii || !rd.object(*radii, "min_edge_radius_m")) return fail();
    for (auto it = radii->begin(); it != radii->end(); ++it) {
        if (it.key() != "default" && !required.contains(it.key())) {
            rd.fail("min_edge_radius_m: unknown class '" + it.key() + "'"); return fail();
        }
        if (!it.value().is_number_integer() || it.value().get<std::int64_t>() < 1 || it.value().get<std::int64_t>() > 100000) {
            rd.fail("min_edge_radius_m." + it.key() + " must be an integer in [1, 100000]"); return fail();
        }
    }
    std::int32_t default_radius = 0;
    if (!rd.integer(*radii, "min_edge_radius_m", "default", 1, 100000, default_radius)) return fail();

    const auto* classes = rd.field(j, "root", "classes");
    if (!classes || !rd.object(*classes, "classes")) return fail();
    for (auto it = classes->begin(); it != classes->end(); ++it)
        if (!required.contains(it.key())) { rd.fail("classes: unknown class '" + it.key() + "'"); return fail(); }
    for (const auto& name : required) {
        const auto it = classes->find(name);
        if (it == classes->end()) { rd.fail("classes: missing class '" + name + "'"); return fail(); }
        const std::string path = "classes." + name;
        const json& c = *it;
        if (!rd.keys(c, path, {"single_lane_both", "single_lane_mm", "oneway_lanes", "twoway_lanes", "lane_mm", "outer_lane_mm",
                "shoulder_outer_mm", "shoulder_inner_mm", "verge_mm", "markings_default", "taper"})) return fail();
        RoadClassRules out; out.highway = name;
        if (!rd.boolean(c, path, "single_lane_both", out.single_lane_both, true)) return fail();
        if (out.single_lane_both) {
            for (const char* k : {"oneway_lanes", "twoway_lanes", "lane_mm", "outer_lane_mm"})
                if (c.contains(k)) { rd.fail(path + "." + k + " is not allowed with single_lane_both"); return fail(); }
            if (!rd.integer(c, path, "single_lane_mm", rules.min_lane_mm, kMaxMm, out.single_lane_mm)) return fail();
            out.oneway_lanes = 1; out.twoway_lanes = 1; out.lane_mm = out.single_lane_mm;
        } else {
            if (c.contains("single_lane_mm")) { rd.fail(path + ".single_lane_mm needs single_lane_both"); return fail(); }
            if (!rd.integer(c, path, "oneway_lanes", 1, 16, out.oneway_lanes) ||
                !rd.integer(c, path, "twoway_lanes", 1, 16, out.twoway_lanes) ||
                !rd.integer(c, path, "lane_mm", rules.min_lane_mm, kMaxMm, out.lane_mm) ||
                !rd.integer(c, path, "outer_lane_mm", rules.min_lane_mm, kMaxMm, out.outer_lane_mm, true)) return fail();
        }
        if (!rd.integer(c, path, "shoulder_outer_mm", 0, kMaxMm, out.shoulder_outer_mm, true) ||
            !rd.integer(c, path, "shoulder_inner_mm", 0, kMaxMm, out.shoulder_inner_mm, true) ||
            !rd.integer(c, path, "verge_mm", 0, kMaxMm, out.verge_mm) ||
            !rd.boolean(c, path, "markings_default", out.markings_default)) return fail();
        const auto* taper = rd.field(c, path, "taper");
        const auto tp = path + ".taper";
        if (!taper || !rd.keys(*taper, tp, {"lane_add_m", "width_change_m", "edge_band_m", "shift_m_per_m", "shift_min_m", "shift_max_m"}))
            return fail();
        if (!rd.integer(*taper, tp, "lane_add_m", 1, 1000, out.taper.lane_add_m) ||
            !rd.integer(*taper, tp, "width_change_m", 1, 1000, out.taper.width_change_m) ||
            !rd.integer(*taper, tp, "edge_band_m", 1, 1000, out.taper.edge_band_m) ||
            !rd.integer(*taper, tp, "shift_m_per_m", 1, 1000, out.taper.shift_m_per_m) ||
            !rd.integer(*taper, tp, "shift_min_m", 1, 2000, out.taper.shift_min_m) ||
            !rd.integer(*taper, tp, "shift_max_m", 1, 2000, out.taper.shift_max_m)) return fail();
        if (out.taper.shift_min_m > out.taper.shift_max_m) { rd.fail(tp + ": shift_min_m exceeds shift_max_m"); return fail(); }
        const auto own = radii->find(name);
        out.min_edge_radius_m = own != radii->end() ? own->get<std::int32_t>() : default_radius;
        // A lateral S-ramp of a lane width W over a taper a has maximum curvature 4 W / a^2, which may not
        // exceed 1 / min_edge_radius_m: 4 W R <= a^2, in integers 4 * W_mm * R <= 1000 * a^2.
        const std::int64_t widest = std::max({out.lane_mm, out.outer_lane_mm, out.single_lane_mm});
        const std::int64_t a = out.taper.lane_add_m;
        if (4 * widest * out.min_edge_radius_m > 1000 * a * a) {
            rd.fail(tp + ".lane_add_m too short for min_edge_radius_m " + std::to_string(out.min_edge_radius_m)); return fail();
        }
        rules.classes.push_back(std::move(out));
    }
    // std::set iterates ascending, so the classes are sorted by highway value.
    rules.content_sha256 = Sha256::of(bytes);
    return rules;
}

std::span<const std::byte> builtin_road_rules_de_bytes() {
    return {reinterpret_cast<const std::byte*>(kRoadRulesDe), sizeof(kRoadRulesDe)};
}
const RoadRules& builtin_road_rules_de() {
    static const RoadRules rules = [] {
        auto loaded = load_road_rules(builtin_road_rules_de_bytes());
        if (!loaded) {
            std::fprintf(stderr, "g2m: embedded data/road_rules/de.json is invalid: %s\n", loaded.error().message.c_str());
            std::abort();
        }
        return std::move(*loaded);
    }();
    return rules;
}
} // namespace g2m
